input.command:
gh api graphql -f query='query {
  repository(owner:"entireio", name:"cli") {
    pullRequest(number:1862) {
      reviewThreads(first:100) {
        nodes {
          id isResolved isOutdated path line
          comments(first:20) {
            nodes { databaseId author { login } body createdAt }
          }
        }
      }
    }
  }
}' 2>&1 | head -100

RESET=1785148684
NOW=$(date +%s)
WAIT=$(( RESET - NOW + 8 ))
[ $WAIT -lt 0 ] && WAIT=0
sleep $WAIT

# Fetch threads, find the unresolved thread containing our comment, resolve it
TID=$(gh api graphql -f query='query {
  repository(owner:"entireio", name:"cli") {
    pullRequest(number:1862) {
      reviewThreads(first:100) {
        nodes { id isResolved comments(first:20){ nodes { databaseId } } }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | select(any(.comments.nodes[]; .databaseId==3656105775)) | .id')

echo "thread id: $TID"
if [ -n "$TID" ]; then
  gh api graphql -f query='mutation($id: ID!){ resolveReviewThread(input:{threadId:$id}){ thread { isResolved } } }' -F id="$TID" --jq '.data.resolveReviewThread.thread.isResolved'
fi
echo "=== remaining unresolved threads ==="
gh api graphql -f query='query {
  repository(owner:"entireio", name:"cli") {
    pullRequest(number:1862) {
      reviewThreads(first:100) { nodes { id isResolved } }
    }
  }
}' --jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false)] | length'
